# Generated by build_installer.py; same core as the Shell entrypoint.
[CmdletBinding()]
param(
  [ValidateSet('stable')][string]$Channel,
  [string]$Version,
  [ValidateSet('codex','claude-code')][string[]]$Agent,
  [switch]$NoModifyPath
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$Base = 'https://github.com/shotlab/shotlab-cli/releases/download/installer-v1.5.1'
$DistributionAudience = 'public'
$CoreSha = 'c3e414afb721d1c1ba2fb89f3b22b75ece98e670f9d69ab20c9ac6c1a773ccc2'
$NodeVersion = '24.22.0'
$NodeSha = 'f9683a19877e12a9b167305c8db71040d812876359de21f0d2e97c3f321f80c3'
$Root = Join-Path $env:LOCALAPPDATA 'Shotlab\installer'
$Scratch = Join-Path ([IO.Path]::GetTempPath()) ('shotlab-setup-' + [Guid]::NewGuid())
$RuntimeLock = $null
function Assert-NoLink([string]$Target) {
  for ($p = $Target; $p; $p = Split-Path -Parent $p) {
    if ((Test-Path -LiteralPath $p) -and ((Get-Item -Force -LiteralPath $p).Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw "安装路径不能包含链接：$p" }
  }
}
function Fetch([string]$Url, [string]$Out) {
  # Disable automatic redirects so an HTTPS download cannot downgrade to HTTP.
  for ($i = 0; $i -lt 6; $i++) {
    $uri = [Uri]$Url
    if ($uri.Scheme -ne 'https' -or $uri.UserInfo) { throw '只允许匿名 HTTPS 下载' }
    $request = [Net.HttpWebRequest]::Create($uri)
    $request.AllowAutoRedirect = $false
    $request.Timeout = 120000
    $response = $request.GetResponse()
    try {
      if ([int]$response.StatusCode -in @(301,302,303,307,308)) { $Url = ([Uri]::new($uri, $response.Headers['Location'])).AbsoluteUri; continue }
      if ([int]$response.StatusCode -ne 200) { throw "下载失败 HTTP $($response.StatusCode)" }
      $output = [IO.File]::Create($Out)
      try { $response.GetResponseStream().CopyTo($output) } finally { $output.Dispose() }
      return
    } finally { $response.Dispose() }
  }
  throw '下载重定向过多'
}
try {
  if ($env:OS -ne 'Windows_NT' -or -not [Environment]::Is64BitOperatingSystem -or $env:PROCESSOR_ARCHITECTURE -eq 'ARM64' -or $env:PROCESSOR_ARCHITEW6432 -eq 'ARM64') { throw '此入口支持 Windows x64；macOS/Linux 请运行 install.sh。' }
  [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
  Assert-NoLink $Root
  New-Item -ItemType Directory -Path $Scratch | Out-Null
  $Core = Join-Path $Scratch 'installer.mjs'
  if ($PSScriptRoot -and (Test-Path -LiteralPath (Join-Path $PSScriptRoot 'installer.mjs'))) { Copy-Item -LiteralPath (Join-Path $PSScriptRoot 'installer.mjs') -Destination $Core }
  
  else { Fetch "$Base/installer.mjs" $Core }
  if ((Get-FileHash -Algorithm SHA256 -LiteralPath $Core).Hash.ToLowerInvariant() -ne $CoreSha) { throw '共享安装逻辑 SHA-256 不一致' }
  $Node = $null
  if ((Get-Command node -ErrorAction SilentlyContinue) -and (Get-Command npx -ErrorAction SilentlyContinue)) {
    & node -e 'const [a,b]=process.versions.node.split(".").map(Number);process.exit(a>22||(a===22&&b>=20)?0:1)'
    if ($LASTEXITCODE -eq 0) { $Node = (Get-Command node).Source }
  }
  if (-not $Node) {
    $Runtime = Join-Path $Root "runtime\node-v$NodeVersion-win-x64"
    Assert-NoLink $Runtime
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Runtime) | Out-Null
    $Lock = Join-Path $Root 'runtime\lock'
    New-Item -ItemType Directory -Path $Lock -ErrorAction Stop | Out-Null
    $RuntimeLock = $Lock
    if (-not (Test-Path -LiteralPath $Runtime)) {
      Write-Host "安装专用 Node $NodeVersion（不替换系统 Node）…"
      $Archive = Join-Path $Scratch 'node.zip'
      Fetch "https://nodejs.org/dist/v$NodeVersion/node-v$NodeVersion-win-x64.zip" $Archive
      if ((Get-FileHash -Algorithm SHA256 -LiteralPath $Archive).Hash.ToLowerInvariant() -ne $NodeSha) { throw 'Node SHA-256 校验失败' }
      Expand-Archive -LiteralPath $Archive -DestinationPath $Scratch
      Move-Item -LiteralPath (Join-Path $Scratch "node-v$NodeVersion-win-x64") -Destination $Runtime
    }
    $Node = Join-Path $Runtime 'node.exe'
    if (-not (Test-Path -LiteralPath (Join-Path $Runtime 'node_modules\npm\bin\npx-cli.js'))) { throw "运行时不完整：$Runtime；请备份并移出后重试。" }
    if ((& $Node --version) -ne "v$NodeVersion") { throw '专用运行时版本不一致' }
    Remove-Item -LiteralPath $RuntimeLock; $RuntimeLock = $null
    $env:PATH = "$Runtime;$env:PATH"
  }
  $Arguments = @($Core)
  if ($Channel) { $Arguments += @('--channel', $Channel) }
  if ($Version) { $Arguments += @('--version', $Version) }
  foreach ($a in $Agent) { $Arguments += @('--agent', $a) }
  if ($NoModifyPath) { $Arguments += '--no-modify-path' }
  & $Node @Arguments
  if ($LASTEXITCODE -ne 0) { throw "Shotlab 安装器退出码 $LASTEXITCODE" }
} finally {
  if (Test-Path -LiteralPath $Scratch) { Remove-Item -LiteralPath $Scratch -Recurse -Force }
  if ($RuntimeLock) { Remove-Item -LiteralPath $RuntimeLock }
}
